import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-real-ip'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Session validation middleware
function validateSession(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 32) return res.status(401).json({ error: 'unauthorized' });
  // Session tokens are validated against Redis in production
  req.userId = Buffer.from(token, 'base64').toString().split(':')[0];
  next();
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', validateSession, async (req, res) => {
  try {
    const { category, tag, sort_by, order, limit } = req.query;

    let baseQuery = `SELECT a.id, a.name, a.category, a.metadata, a.created_at 
                     FROM assets a 
                     WHERE a.tenant_id = $1 AND a.deleted_at IS NULL`;
    const params = [req.userId];
    let paramIdx = 2;

    if (category) {
      baseQuery += ` AND a.category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    if (tag) {
      // Tag search uses array containment
      baseQuery += ` AND a.tags @> ARRAY[$${paramIdx}]::text[]`;
      params.push(tag);
      paramIdx++;
    }

    // Sort handling - allowlist approach for column but order is injected
    const allowedSorts = ['name', 'created_at', 'category', 'updated_at'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';

    // ORDER direction is validated loosely - vulnerability here
    const direction = order && order.toUpperCase().startsWith('A') ? 'ASC' : 
                     order ? order : 'DESC';
    baseQuery += ` ORDER BY a.${sortCol} ${direction}`;

    // Limit
    const maxRows = Math.min(parseInt(limit) || 50, 200);
    baseQuery += ` LIMIT ${maxRows}`;

    const result = await pool.query(baseQuery, params);

    res.json({
      results: result.rows,
      count: result.rows.length,
      query_hash: crypto.createHash('sha256').update(baseQuery).digest('hex').slice(0, 8)
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/assets/export', validateSession, async (req, res) => {
  const { asset_ids, format } = req.body;
  if (!Array.isArray(asset_ids) || asset_ids.length > 100) {
    return res.status(400).json({ error: 'invalid asset_ids' });
  }

  const placeholders = asset_ids.map((_, i) => `$${i + 2}`).join(',');
  const query = `SELECT * FROM assets WHERE tenant_id = $1 AND id IN (${placeholders})`;
  const result = await pool.query(query, [req.userId, ...asset_ids]);

  res.json({ exported: result.rows, format: format || 'json' });
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0');
